CREATE TYPE "ReservationStatus" AS ENUM ('ACTIVE', 'RELEASED', 'EXPIRED');
CREATE TABLE "reservations" ("id" TEXT NOT NULL,"patient_id" TEXT NOT NULL,"prescription_id" TEXT NOT NULL,"idempotency_key" TEXT NOT NULL,"status" "ReservationStatus" NOT NULL DEFAULT 'ACTIVE',"expires_at" TIMESTAMP(3) NOT NULL,"released_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "reservations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "reservation_allocations" ("id" TEXT NOT NULL,"reservation_id" TEXT NOT NULL,"prescription_item_id" TEXT NOT NULL,"pharmacy_id" TEXT NOT NULL,"quote_item_id" TEXT NOT NULL,"quote_revision" INTEGER NOT NULL,"inventory_item_id" TEXT NOT NULL,"selected_quantity" INTEGER NOT NULL,"unit_price_minor" INTEGER NOT NULL,"line_total_minor" INTEGER NOT NULL,"expires_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "reservation_allocations_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "reservations_patient_id_idempotency_key_key" ON "reservations"("patient_id","idempotency_key");
CREATE INDEX "reservations_patient_id_status_expires_at_idx" ON "reservations"("patient_id","status","expires_at"); CREATE INDEX "reservations_prescription_id_status_idx" ON "reservations"("prescription_id","status"); CREATE INDEX "reservation_allocations_reservation_id_idx" ON "reservation_allocations"("reservation_id"); CREATE INDEX "reservation_allocations_inventory_item_id_idx" ON "reservation_allocations"("inventory_item_id");
ALTER TABLE "reservations" ADD CONSTRAINT "reservations_patient_id_fkey" FOREIGN KEY ("patient_id") REFERENCES "users"("id") ON DELETE CASCADE; ALTER TABLE "reservations" ADD CONSTRAINT "reservations_prescription_id_fkey" FOREIGN KEY ("prescription_id") REFERENCES "prescriptions"("id") ON DELETE CASCADE; ALTER TABLE "reservation_allocations" ADD CONSTRAINT "reservation_allocations_reservation_id_fkey" FOREIGN KEY ("reservation_id") REFERENCES "reservations"("id") ON DELETE CASCADE; ALTER TABLE "reservation_allocations" ADD CONSTRAINT "reservation_allocations_pharmacy_id_fkey" FOREIGN KEY ("pharmacy_id") REFERENCES "pharmacies"("id") ON DELETE RESTRICT; ALTER TABLE "reservation_allocations" ADD CONSTRAINT "reservation_allocations_quote_item_id_fkey" FOREIGN KEY ("quote_item_id") REFERENCES "pharmacy_quote_items"("id") ON DELETE RESTRICT; ALTER TABLE "reservation_allocations" ADD CONSTRAINT "reservation_allocations_inventory_item_id_fkey" FOREIGN KEY ("inventory_item_id") REFERENCES "pharmacy_inventory_items"("id") ON DELETE RESTRICT;
